package com.careflow.hospital.appointments;
import com.careflow.hospital.audit.AuditService;import com.careflow.hospital.doctors.*;import com.careflow.hospital.outbox.OutboxService;import com.careflow.hospital.patients.*;import com.careflow.hospital.reservations.SlotReservationRepository;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AppointmentServiceTest {
 @Test void doctorOnlyReceivesAppointmentsAssignedToTheirDoctorProfile(){var appointments=mock(AppointmentRepository.class);var patients=mock(PatientRepository.class);var doctors=mock(DoctorRepository.class);var doctor=mock(Doctor.class);var appointment=mock(Appointment.class);var patient=mock(Patient.class);UUID userId=UUID.randomUUID(),doctorId=UUID.randomUUID(),patientId=UUID.randomUUID();when(doctor.getId()).thenReturn(doctorId);when(doctor.isActive()).thenReturn(true);when(doctors.findByUserId(userId)).thenReturn(Optional.of(doctor));when(appointment.getPatientId()).thenReturn(patientId);when(appointments.findAllByDoctorIdOrderByStartsAtDesc(doctorId)).thenReturn(List.of(appointment));when(patients.findById(patientId)).thenReturn(Optional.of(patient));when(patient.getFullName()).thenReturn("Assigned Patient");var service=new AppointmentService(appointments,mock(SlotReservationRepository.class),patients,doctors,mock(AuditService.class),mock(OutboxService.class));var result=service.doctorAppointments(userId);assertEquals(1,result.size());assertEquals("Assigned Patient",result.get(0).patientName());verify(appointments).findAllByDoctorIdOrderByStartsAtDesc(doctorId);verifyNoMoreInteractions(appointments);}

 @Test void reschedulePreservesOriginalAndCreatesProtectedConfirmedReplacement(){var appointments=mock(AppointmentRepository.class);var reservations=mock(SlotReservationRepository.class);var patients=mock(PatientRepository.class);var audit=mock(AuditService.class);var outbox=mock(OutboxService.class);UUID userId=UUID.randomUUID(),patientId=UUID.randomUUID(),oldDoctorId=UUID.randomUUID(),newDoctorId=UUID.randomUUID(),reservationId=UUID.randomUUID();var patient=mock(Patient.class);when(patient.getId()).thenReturn(patientId);when(patients.findByUserId(userId)).thenReturn(Optional.of(patient));var oldStart=java.time.Instant.now().plusSeconds(86400);var original=new Appointment(patientId,oldDoctorId,UUID.randomUUID(),oldStart,oldStart.plusSeconds(1800));var newStart=oldStart.plusSeconds(3600);var reservation=new com.careflow.hospital.reservations.SlotReservation(patientId,newDoctorId,newStart,newStart.plusSeconds(1800),java.time.Instant.now().plusSeconds(300));when(appointments.findByIdForUpdate(original.getId())).thenReturn(Optional.of(original));when(reservations.findByIdForUpdate(reservationId)).thenReturn(Optional.of(reservation));when(appointments.saveAndFlush(any())).thenAnswer(invocation->invocation.getArgument(0));var service=new AppointmentService(appointments,reservations,patients,mock(DoctorRepository.class),audit,outbox);var result=service.reschedule(userId,original.getId(),reservationId);assertEquals("RESCHEDULED",original.getStatus());assertEquals(result.appointmentId(),original.getRescheduledToAppointmentId());assertEquals(original.getId(),result.rescheduledFromAppointmentId());assertEquals("CONFIRMED",result.status());assertEquals(newStart,result.startsAt());assertEquals("CONSUMED",reservation.getStatus());verify(audit).record(userId,"APPOINTMENT_RESCHEDULED_FROM","APPOINTMENT",original.getId(),"SUCCESS");}
}
